// instructions.json is generated by `pdf/pede-assim/build.py --site-data`. Don't edit it by hand.
import data from './instructions.json'

export interface Instruction {
  number: number
  slug: string
  title: string
  when: string
  fields: string
  prompt: string
}

export interface InstructionGroup {
  title: string
  items: Instruction[]
}

export const GROUPS: InstructionGroup[] = data.groups

export const INSTRUCTIONS: Instruction[] = GROUPS.flatMap((group) => group.items)

export function findInstruction(slug: string): Instruction | undefined {
  return INSTRUCTIONS.find((item) => item.slug === slug)
}
